/// Create a `GossipVerifiedDataColumn` from `DataColumnSidecar` for block production ONLY.
/// When publishing a block constructed locally, the EL will have already verified the cell proofs.
pub fn new_for_block_publishing(
    column_sidecar: Arc<DataColumnSidecar<T::EthSpec>>,
    chain: &BeaconChain<T>,
) -> Result<Self, GossipDataColumnError> {
    verify_data_column_sidecar(&column_sidecar)?;
    // Check if already in DA checker cache (happens when made available through engine_getBlobs).
    // If it exists in the cache, we know it has already passed gossip checks.
    verify_is_unknown_sidecar(chain, &column_sidecar)?;
    if chain.data_availability_checker.is_data_column_cached(&column_sidecar.block_root(), &column_sidecar) {
        if O::observe() { observe_gossip_data_column(&column_sidecar, chain)?; }
        return Err(GossipDataColumnError::PriorKnownUnpublished);
    }
    Ok(Self { block_root: column_sidecar.block_root(), data_column: KzgVerifiedDataColumn::from_execution_verified(column_sidecar), _phantom: Default::default() })
}

