fn publish_data_columns_gradually(self: &Arc<Self>, mut data_columns_to_publish: DataColumnSidecarList<T::EthSpec>, block_root: Hash256) {
    self.executor.spawn(async move {
        let publish_fn = |columns: DataColumnSidecarList<T::EthSpec>| {
            self_clone.send_network_message(NetworkMessage::Publish {
                messages: columns.into_iter().map(|d| {
                    let subnet = DataColumnSubnetId::from_column_index(d.index, &chain.spec);
                    PubsubMessage::DataColumnSidecar(Box::new((subnet, d)))
                }).collect(),
            });
        };
        // Permute columns and batch publish...
        for batch in data_columns_to_publish.chunks(batch_size) {
            let publishable = batch.iter().filter_map(|col| match observe_gossip_data_column(col, &chain) {
                Ok(()) => Some(col.clone()),
                Err(GossipDataColumnError::PriorKnown { .. }) => None,
                Err(e) => { warn!(error = ?e, "Previously verified data column is invalid"); None }
            }).collect::<Vec<_>>();
            if !publishable.is_empty() { publish_fn(publishable); }
        }
    }, "publish_data_columns");
}

