pub fn update_eth2_enr(&mut self, enr_fork_id: EnrForkId) {
    // EnrForkId SSZ encoding: fork_digest(4) + next_fork_version(4) + next_fork_epoch(8) = 16 bytes
    let _ = self.discv5.enr_insert::<Bytes>(ETH2_ENR_KEY, &enr_fork_id.as_ssz_bytes().into()).map_err(|e| {
        warn!(error = ?e, "Could not update eth2 ENR field")
    });
    *self.network_globals.local_enr.write() = self.discv5.local_enr();
}

